"use strict";(self.webpackChunkpendle_documentation=self.webpackChunkpendle_documentation||[]).push([[6630],{309:e=>{e.exports=JSON.parse('{"version":{"pluginId":"boros-docs","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"myAutogeneratedSidebar":[{"type":"link","label":"Introduction","href":"/boros-docs/Introduction","customProps":{"icon":"auto_stories"},"docId":"Introduction","unlisted":false},{"type":"category","label":"About Boros","customProps":{"icon":"info"},"items":[{"type":"link","label":"Glossary","href":"/boros-docs/about-boros/glossary","customProps":{"icon":"library_books"},"docId":"about-boros/glossary","unlisted":false},{"type":"link","label":"Market Types","href":"/boros-docs/about-boros/market-types","customProps":{"icon":"category"},"docId":"about-boros/market-types","unlisted":false},{"type":"link","label":"Spread Markets","href":"/boros-docs/about-boros/spread-markets","customProps":{"icon":"compare_arrows"},"docId":"about-boros/spread-markets","unlisted":false},{"type":"link","label":"Rate Settlement","href":"/boros-docs/about-boros/rate-settlement","customProps":{"icon":"receipt_long"},"docId":"about-boros/rate-settlement","unlisted":false},{"type":"link","label":"Implied APR and Position Sizing","href":"/boros-docs/about-boros/implied-apr-and-position-sizing","customProps":{"icon":"currency_exchange"},"docId":"about-boros/implied-apr-and-position-sizing","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Boros Systems","customProps":{"icon":"shield"},"items":[{"type":"link","label":"Order Book","href":"/boros-docs/boros-systems/orderbook","customProps":{"icon":"account_balance"},"docId":"boros-systems/orderbook","unlisted":false},{"type":"link","label":"Margin And Liquidations","href":"/boros-docs/boros-systems/margin-and-liquidations","customProps":{"icon":"calculate"},"docId":"boros-systems/margin-and-liquidations","unlisted":false},{"type":"link","label":"Protective Mechanisms","href":"/boros-docs/boros-systems/protective-mechanism","customProps":{"icon":"security"},"docId":"boros-systems/protective-mechanism","unlisted":false},{"type":"link","label":"Fees","href":"/boros-docs/boros-systems/fees","customProps":{"icon":"payments"},"docId":"boros-systems/fees","unlisted":false},{"type":"link","label":"Incentives","href":"/boros-docs/boros-systems/incentives","customProps":{"icon":"redeem"},"docId":"boros-systems/incentives","unlisted":false},{"type":"link","label":"P2P Marketplace","href":"/boros-docs/boros-systems/p2p-marketplace","customProps":{"icon":"handshake"},"docId":"boros-systems/p2p-marketplace","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Arbitrage with CrossEx","customProps":{"icon":"sync_alt"},"items":[{"type":"link","label":"Overview","href":"/boros-docs/arbitrage-with-crossex/overview","customProps":{"icon":"auto_stories"},"docId":"arbitrage-with-crossex/overview","unlisted":false},{"type":"link","label":"Installation","href":"/boros-docs/arbitrage-with-crossex/installation","customProps":{"icon":"download"},"docId":"arbitrage-with-crossex/installation","unlisted":false},{"type":"link","label":"Setting up CrossEx & API Key","href":"/boros-docs/arbitrage-with-crossex/setup-api-key","customProps":{"icon":"vpn_key"},"docId":"arbitrage-with-crossex/setup-api-key","unlisted":false},{"type":"link","label":"Connecting API + Wallet","href":"/boros-docs/arbitrage-with-crossex/connecting-terminal","customProps":{"icon":"link"},"docId":"arbitrage-with-crossex/connecting-terminal","unlisted":false},{"type":"link","label":"Opening a Position","href":"/boros-docs/arbitrage-with-crossex/opening-a-position","customProps":{"icon":"trending_up"},"docId":"arbitrage-with-crossex/opening-a-position","unlisted":false},{"type":"link","label":"Monitoring & Closing Positions","href":"/boros-docs/arbitrage-with-crossex/monitoring-and-closing","customProps":{"icon":"monitoring"},"docId":"arbitrage-with-crossex/monitoring-and-closing","unlisted":false},{"type":"link","label":"Understanding Position PnL","href":"/boros-docs/arbitrage-with-crossex/position-pnl","customProps":{"icon":"calculate"},"docId":"arbitrage-with-crossex/position-pnl","unlisted":false},{"type":"link","label":"Risks & Security","href":"/boros-docs/arbitrage-with-crossex/risks-and-security","customProps":{"icon":"security"},"docId":"arbitrage-with-crossex/risks-and-security","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Others","customProps":{"icon":"more_horiz"},"items":[{"type":"link","label":"Boros Referral Program","href":"/boros-docs/others/boros-referral-program","customProps":{"icon":"share"},"docId":"others/boros-referral-program","unlisted":false}],"collapsed":true,"collapsible":true}]},"docs":{"about-boros/glossary":{"id":"about-boros/glossary","title":"Glossary","description":"YU (Yield Units): Each YU represents the floating rate earned on 1 unit of collateral. For example, in a BTCUSDT (Hyperliquid) market with BTC as collateral, each YU represents the funding rate of 1 BTC on Hyperliquid. In the BTC Spread HL-Gate market, each YU represents the Hyperliquid-minus-Gate funding spread on 1 BTC.","sidebar":"myAutogeneratedSidebar"},"about-boros/implied-apr-and-position-sizing":{"id":"about-boros/implied-apr-and-position-sizing","title":"Implied APR and Position Sizing","description":"Implied APR and Fixed APR","sidebar":"myAutogeneratedSidebar"},"about-boros/market-types":{"id":"about-boros/market-types","title":"Market Types","description":"Every Boros market trades one floating rate against a fixed rate until maturity. What changes from one market to the next is the rate. The trading mechanics stay the same. Boros currently lists two types of markets, shown under the Funding and Spread tabs on the markets page.","sidebar":"myAutogeneratedSidebar"},"about-boros/rate-settlement":{"id":"about-boros/rate-settlement","title":"Rate Settlement","description":"How Boros Positions Work","sidebar":"myAutogeneratedSidebar"},"about-boros/spread-markets":{"id":"about-boros/spread-markets","title":"Spread Markets","description":"On a given day, BTC funding might be 10% APR on Hyperliquid and 7% APR on Gate. That 3% gap is a rate in its own right. It moves, and it can be forecast. A Spread Market lets you trade that gap directly, as a single position.","sidebar":"myAutogeneratedSidebar"},"adlMechanics":{"id":"adlMechanics","title":"Boros \u2014 Deleveraging and Liquidation Mechanism Disclosure","description":"Nature of This Document. This document is published to provide users with information about the Boros protocol\'s risk management, liquidation, and auto-deleveraging mechanisms as currently designed and understood. It is informational only. Nothing in this document constitutes a warranty, guarantee, contractual commitment, financial advice, legal advice, or investment advice of any kind."},"arbitrage-with-crossex/connecting-terminal":{"id":"arbitrage-with-crossex/connecting-terminal","title":"Connecting API + Wallet","description":"Open http6688 to load Arbitrage with CrossEx on your device.","sidebar":"myAutogeneratedSidebar"},"arbitrage-with-crossex/installation":{"id":"arbitrage-with-crossex/installation","title":"Installation","description":"The app runs on your own machine \u2014 macOS or Windows. See boros.pendle.finance/arbitrage-crossex for an overview, or GitHub for full instructions and source: github.com/pendle-finance/arbitrage-with-crossex.","sidebar":"myAutogeneratedSidebar"},"arbitrage-with-crossex/monitoring-and-closing":{"id":"arbitrage-with-crossex/monitoring-and-closing","title":"Monitoring & Closing Positions","description":"The Positions tab","sidebar":"myAutogeneratedSidebar"},"arbitrage-with-crossex/opening-a-position":{"id":"arbitrage-with-crossex/opening-a-position","title":"Opening a Position","description":"Both halves of the trade are executed from the terminal: the rate lock on Boros (a single Spread Market position, or two Funding Market legs) and the perp legs through CrossEx. The guided wizard walks you through both in the right order \u2014 lock the rate first, then hedge the perps \u2014 since Boros price impact is higher and less predictable, so you want the spread secured before committing to the perp side.","sidebar":"myAutogeneratedSidebar"},"arbitrage-with-crossex/overview":{"id":"arbitrage-with-crossex/overview","title":"Overview","description":"Arbitrage with CrossEx is a free, open-source tool built by the Pendle team that lets traders run a cross-exchange funding-rate arbitrage through Gate CrossEx and Boros, from a single dashboard on their own machine.","sidebar":"myAutogeneratedSidebar"},"arbitrage-with-crossex/position-pnl":{"id":"arbitrage-with-crossex/position-pnl","title":"Understanding Position PnL","description":"Every position box reports a return on capital. Two things decide that number: which costs are charged to the position, and what counts as the capital it consumed. Both are adjustable, and both matter \u2014 the same trade can read very differently depending on how they\'re set.","sidebar":"myAutogeneratedSidebar"},"arbitrage-with-crossex/risks-and-security":{"id":"arbitrage-with-crossex/risks-and-security","title":"Risks & Security","description":"Arbitrage with CrossEx is free, open-source, experimental software published by Pendle. It places real orders with real funds on your own exchange account and can lose money. Nothing here is financial, investment, legal, or tax advice \u2014 see the full disclaimer.","sidebar":"myAutogeneratedSidebar"},"arbitrage-with-crossex/setup-api-key":{"id":"arbitrage-with-crossex/setup-api-key","title":"Setting up CrossEx & API Key","description":"1. Enable CrossEx","sidebar":"myAutogeneratedSidebar"},"boros-systems/fees":{"id":"boros-systems/fees","title":"Fees","description":"Boros charges four types of fees. All fees are denominated in the collateral asset of the relevant market and deducted directly from your collateral balance.","sidebar":"myAutogeneratedSidebar"},"boros-systems/incentives":{"id":"boros-systems/incentives","title":"Incentives","description":"Boros runs two distinct incentive programs: one for resting limit orders that provide liquidity within a defined rate boundary, and one that returns a portion of taker fees to the makers those takers fill against.","sidebar":"myAutogeneratedSidebar"},"boros-systems/margin-and-liquidations":{"id":"boros-systems/margin-and-liquidations","title":"Margin & Liquidations","description":"Understanding Your Position\'s Risk","sidebar":"myAutogeneratedSidebar"},"boros-systems/orderbook":{"id":"boros-systems/orderbook","title":"Order Book","description":"Boros operates a central limit order book (CLOB) for trading interest rate swaps (YU).","sidebar":"myAutogeneratedSidebar"},"boros-systems/p2p-marketplace":{"id":"boros-systems/p2p-marketplace","title":"P2P Marketplace","description":"The P2P Marketplace lets you negotiate sized swaps directly with a counterparty instead of trading through the order book.","sidebar":"myAutogeneratedSidebar"},"boros-systems/protective-mechanism":{"id":"boros-systems/protective-mechanism","title":"Protective Mechanisms","description":"Boros has multiple protective risk systems, a set of interventions at various level of forcefulness designed to protect the protocol from bad debt. Under normal conditions, most of these mechanisms are invisible. They activate in response to deteriorating health ratios, extreme rate movements, or rising open interest. Understanding them helps traders anticipate how their positions and orders might be affected.","sidebar":"myAutogeneratedSidebar"},"Introduction":{"id":"Introduction","title":"Boros Overview","description":"Boros is a rate-trading platform on margin by Pendle. Each Boros market tracks a floating rate, and lets you trade that rate against a fixed one until maturity. Any rate with a reliable oracle feed can be listed as a market.","sidebar":"myAutogeneratedSidebar"},"others/boros-referral-program":{"id":"others/boros-referral-program","title":"Boros Referral Program","description":"You can access the referral page at Boros\' account page//boros.pendle.finance/account","sidebar":"myAutogeneratedSidebar"}}}}')}}]);